from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

# Marker / cache bust
s=s.replace('<!-- pages-publish: shumagh-manual-details-2026-08-25 -->','<!-- pages-publish: shumagh-fixed-choices-2026-08-25 -->',1)

# Replace Shumagh UI block
pattern=r'<div id="shortShumaghBox" class="hidden">.*?</div></div><div class="card wide"><div class="title">السجل</div>'
new='''<div id="shortShumaghBox" class="hidden"><div class="notice ok"><b>الأشمغة والغتر</b><div style="margin-top:5px">المقاسات والصنف واللون خيارات ثابتة. اختر منها، ثم سجّل النوع والخامة والكميات فقط.</div></div><div class="title" style="margin-top:14px">المقاس</div><div id="shumaghSizeChoices" class="actions" style="justify-content:flex-start;flex-wrap:wrap"></div><div class="title" style="margin-top:14px">الصنف</div><div id="shumaghProductChoices" class="actions" style="justify-content:flex-start;flex-wrap:wrap"><button class="mini" data-value="شماغ" onclick="selectShumaghProduct('شماغ',this)">شماغ</button><button class="mini" data-value="غترة" onclick="selectShumaghProduct('غترة',this)">غترة</button></div><div class="title" style="margin-top:14px">اللون</div><div id="shumaghColorChoices" class="actions" style="justify-content:flex-start;flex-wrap:wrap"><button class="mini" data-value="أحمر" onclick="selectShumaghColor('أحمر',this)">أحمر</button><button class="mini" data-value="أبيض" onclick="selectShumaghColor('أبيض',this)">أبيض</button></div><div id="shumaghFixedSummary" class="notice" style="margin-top:14px">اختر المقاس والصنف واللون.</div><div id="shumaghSelected" class="task hidden"><div class="fields"><div class="field"><label>النوع</label><input id="shumaghType" placeholder="مثال: اليزية"></div><div class="field"><label>الخامة</label><input id="shumaghMaterial" placeholder="مثال: 2155"></div></div><div class="fields" style="margin-top:10px"><div class="field"><label>الموجود حاليًا</label><input id="shumaghCurrent" inputmode="numeric" value="0"></div><div class="field"><label>المطلوب للتغذية</label><input id="shumaghRequested" inputmode="numeric" value="0"></div><div class="field"><label>الفرص الضائعة</label><input id="shumaghLost" inputmode="numeric" value="0"></div></div><div class="actions" style="justify-content:flex-start"><button class="btn" onclick="addShumaghDraft()">إضافة للنواقص</button></div></div><div class="title" style="margin-top:18px">طلب الأشمغة الحالي</div><div id="shumaghDraftList"><p class="mut">لم تتم إضافة أصناف بعد.</p></div><div class="actions"><span></span><button class="btn gold" onclick="saveShumaghShortages()">حفظ نواقص الأشمغة</button></div></div></div><div class="card wide"><div class="title">السجل</div>'''
s,n=re.subn(pattern,new,s,count=1,flags=re.S)
assert n==1, 'Shumagh UI block not found'

# Add state values
old='winterSelectedItem=null,winterDraft=[],shumaghSelectedItem=null,shumaghDraft=[];'
newstate='winterSelectedItem=null,winterDraft=[],shumaghSelectedItem=null,shumaghProductChoice="",shumaghColorChoice="",shumaghDraft=[];'
assert old in s, 'global Shumagh state marker not found'
s=s.replace(old,newstate,1)

# Reset state on open shortages
old='winterSelectedItem=null;winterDraft=[];shumaghSelectedItem=null;shumaghDraft=[];'
newreset='winterSelectedItem=null;winterDraft=[];shumaghSelectedItem=null;shumaghProductChoice="";shumaghColorChoice="";shumaghDraft=[];'
assert old in s, 'Shumagh reset marker not found'
s=s.replace(old,newreset,1)

# Replace section-init behavior
old="if(isShumagh){shumaghSelectedItem=null;$('shumaghSelected').classList.add('hidden');$('shumaghSearch').value='';$('shumaghResults').innerHTML='<p class=\"mut\">ابدأ بالكتابة للبحث في مقاسات الأشمغة والغتر.</p>';renderShumaghDraft()}"
newinit="if(isShumagh){shumaghSelectedItem=null;shumaghProductChoice='';shumaghColorChoice='';$('shumaghSelected').classList.add('hidden');renderShumaghFixedControls();renderShumaghDraft()}"
assert old in s, 'Shumagh init function marker not found'
s=s.replace(old,newinit,1)

# Replace Shumagh JS functions
pattern=r'function renderShumaghResults\(\).*?function addShortRow\(\)'
funcs=r'''function renderShumaghFixedControls(){$('shumaghSizeChoices').innerHTML=SHUMAGH_SIZES.map((size,i)=>`<button class="mini ${shumaghSelectedItem?.size===size?'on':''}" onclick="selectShumaghItem(${i},this)">${esc(size)}</button>`).join('');document.querySelectorAll('#shumaghProductChoices .mini').forEach(b=>b.classList.toggle('on',b.dataset.value===shumaghProductChoice));document.querySelectorAll('#shumaghColorChoices .mini').forEach(b=>b.classList.toggle('on',b.dataset.value===shumaghColorChoice));updateShumaghFixedSummary()}function selectShumaghItem(i,b){let x=SHUMAGH_CATALOG[i];if(!x)return;shumaghSelectedItem=x;document.querySelectorAll('#shumaghSizeChoices .mini').forEach(v=>v.classList.remove('on'));b?.classList.add('on');updateShumaghFixedSummary()}function selectShumaghProduct(v,b){shumaghProductChoice=v;document.querySelectorAll('#shumaghProductChoices .mini').forEach(x=>x.classList.remove('on'));b?.classList.add('on');updateShumaghFixedSummary()}function selectShumaghColor(v,b){shumaghColorChoice=v;document.querySelectorAll('#shumaghColorChoices .mini').forEach(x=>x.classList.remove('on'));b?.classList.add('on');updateShumaghFixedSummary()}function updateShumaghFixedSummary(){let ready=shumaghSelectedItem&&shumaghProductChoice&&shumaghColorChoice;$('shumaghFixedSummary').innerHTML=ready?`المحدد: <b>${esc(shumaghSelectedItem.size)} — ${esc(shumaghProductChoice)} — ${esc(shumaghColorChoice)}</b>`:'اختر المقاس والصنف واللون.';$('shumaghSelected').classList.toggle('hidden',!ready);if(ready){$('shumaghType').value='';$('shumaghMaterial').value='';$('shumaghCurrent').value='0';$('shumaghRequested').value='0';$('shumaghLost').value='0'}}function addShumaghDraft(){try{if(!shumaghSelectedItem)throw Error('اختر المقاس');if(!shumaghProductChoice)throw Error('اختر الصنف شماغ أو غترة');if(!shumaghColorChoice)throw Error('اختر اللون');let kind=$('shumaghType').value.trim(),material=$('shumaghMaterial').value.trim();if(!kind)throw Error('اكتب النوع');if(!material)throw Error('اكتب الخامة');let label=`${shumaghSelectedItem.size} — ${shumaghProductChoice} — ${shumaghColorChoice} — ${kind} — ${material}`,section=$('shortSection').value,key=label.trim().toLowerCase(),dup=shortagesData.find(q=>{if(q.section_id!==section||String(q.size||'').trim().toLowerCase()!==key||q.shortage_status!=='تم الطلب')return false;let a=q.action_id?app.actions.find(z=>z.id===q.action_id):null;return !a||a.action_status!=='مغلق'});if(dup)throw Error(`هذا الصنف له طلب تغذية قائم بالفعل منذ ${dup.ordered_date||'—'}`);if(shumaghDraft.some(x=>x.label.trim().toLowerCase()===key))throw Error('هذا الصنف مضاف بالفعل في الطلب الحالي');let current=Number($('shumaghCurrent').value||0),requested=Number($('shumaghRequested').value||0),lost=Number($('shumaghLost').value||0);if([current,requested,lost].some(x=>Number.isNaN(x)||x<0))throw Error('أدخل الكميات بشكل صحيح');shumaghDraft.push({label,size:shumaghSelectedItem.size,product:shumaghProductChoice,color:shumaghColorChoice,kind,material,current_qty:current,requested_qty:requested,lost_opportunities:lost});renderShumaghDraft();$('shumaghType').value='';$('shumaghMaterial').value='';$('shumaghCurrent').value='0';$('shumaghRequested').value='0';$('shumaghLost').value='0'}catch(e){alert(e.message)}}function removeShumaghDraft(i){shumaghDraft.splice(i,1);renderShumaghDraft()}function renderShumaghDraft(){$('shumaghDraftList').innerHTML=shumaghDraft.length?shumaghDraft.map((x,i)=>`<div class="task"><b>${esc(x.label)}</b><div class="mut" style="margin-top:6px">الموجود: ${x.current_qty} | المطلوب: ${x.requested_qty} | الفرص الضائعة: ${x.lost_opportunities}</div><div style="margin-top:8px"><button class="mini" style="color:#c83b3b;border-color:#efb4b4" onclick="removeShumaghDraft(${i})">حذف</button></div></div>`).join(''):'<p class="mut">لم تتم إضافة أصناف بعد.</p>'}function addShortRow()'''
s,n=re.subn(pattern,funcs,s,count=1,flags=re.S)
assert n==1, 'Shumagh JS function block not found'

p.write_text(s,encoding='utf-8')
